import numpy as np,scipy.optimize as so,scipy.stats as stats,scipy.special as special,itertools,json,subprocess,warnings
warnings.filterwarnings('ignore',category=RuntimeWarning)
rng=np.random.default_rng(615891);cases=[];skipped=[]
def add(op,data,args,expected):
 cases.append((op+'|'+','.join(map(str,args))+'|'+';'.join(','.join(map(str,r))for r in data),op,expected))
def grad(function,b):
 out=[]
 for j in range(len(b)):
  z=np.array(b,dtype=complex);z[j]+=1e-20j;out.append(np.imag(function(z))/1e-20)
 return np.array(out)
def hessian(gradient,b):
 cols=[]
 for j in range(len(b)):
  d=np.zeros(len(b));d[j]=1e-4
  first=(gradient(b+d)-gradient(b-d))/(2e-4);second=(gradient(b+d/2)-gradient(b-d/2))/1e-4
  cols.append((4*second-first)/3)
 return np.array(cols).T
for model in range(3):
 for iteration in range(40):
  n=int(rng.integers(35,85));p=int(rng.integers(1,4));X=rng.normal(0,1,(n,p));D=np.c_[np.ones(n),X];truth=np.r_[1.3,rng.normal(0,.35,p)];mu=D@truth;sigma=float(rng.uniform(.35,.9))
  if model==0:T=np.exp(mu)*rng.exponential(1,n)
  elif model==1:T=np.exp(mu)*rng.exponential(1,n)**sigma
  else:T=np.exp(mu+sigma*rng.normal(0,1,n))
  C=np.exp(mu)*rng.exponential(4,n);t=np.minimum(T,C);e=(T<=C).astype(int);scales=X.std(0);penalty=.5 if iteration>=30 else 0.
  def ll(b,penalty=penalty):
   location=D@b[:p+1]
   if model==0:likelihood=np.sum(-e*location-t*np.exp(-location))
   else:
    h=b[-1];z=(np.log(t)-location)/np.exp(h)
    if model==1:likelihood=np.sum(e*(-np.log(t)-h+z)-np.exp(z))
    else:likelihood=np.sum(e*(-np.log(t)-h-.5*z*z-.5*np.log(2*np.pi))+(1-e)*special.log_ndtr(-z))
   return likelihood-penalty*np.sum((b[1:p+1]*scales)**2)/2
  guess=np.r_[np.log(t).mean(),np.zeros(p),([]if model==0 else[np.log(np.log(t).std())])]
  g=lambda b:grad(ll,b);optimized=so.minimize(lambda b:-ll(b),guess,jac=lambda b:-g(b),method='BFGS',options={'gtol':1e-9,'maxiter':1000})
  root=so.root(g,optimized.x,tol=1e-10);b=root.x
  if np.max(abs(g(b)))>1e-6 or not np.all(np.isfinite(b)):
   skipped.append((model,iteration,'oracle score'));continue
  info=-hessian(g,b)
  if min(np.linalg.eigvalsh(info))<=0:skipped.append((model,iteration,'oracle information'));continue
  covariance=np.linalg.inv(info);expected={'coefficients':b[:p+1],'log_likelihood':ll(b,penalty=0),'standard_errors':np.sqrt(covariance.diagonal())}
  if model>0:expected['log_sigma']=b[-1]
  add(['aft_exponential','aft_weibull','aft_lognormal'][model],np.c_[X,t,e],[penalty,500.,1e-9],expected)
for model in range(3):
 for _ in range(40):
  mu=float(rng.uniform(-10,10));h=0. if model==0 else float(rng.uniform(-2,1));sigma=np.exp(h);modelvec=[model,0,0,h,mu]
  z=float(rng.choice([-40,-20,-8,-2,0,2,8,20,40]));time=np.exp(mu+sigma*z);q=float(rng.choice([1e-250,1e-20,.001,.1,.5,.9,.9999999999999999]))
  expectedS=np.exp(-np.exp(z)) if model<2 else stats.norm.sf(z)
  add('aft_predict',[[time]],[0,*modelvec],{'survival_probabilities':[expectedS]})
  quantilelog=mu+sigma*np.log(-np.log1p(-q))if model<2 else mu+sigma*stats.norm.ppf(q)
  add('aft_predict',[[q]],[1,*modelvec],{'log_time_quantiles':[quantilelog]})
for _ in range(60):
 n=int(rng.integers(3,40));end=float(np.exp(rng.uniform(-30,30)));times=np.sort(rng.uniform(.001,.999,n))*end;shape=n/np.log(end/times).sum();logeta=np.log(end)-np.log(n)/shape;ll=np.log(shape/end)+shape*(np.log(end)-logeta)+(shape-1)*np.log(times/end)
 add('nhpp_powerlaw',times[:,None],[end],{'shape':shape,'log_eta':logeta,'log_likelihood':ll.sum()-n,'shape_standard_error':shape/np.sqrt(n)})
 query=np.array([0,end/2,end,2*end]);cumulative=np.r_[0,np.exp(shape*(np.log(query[1:])-logeta))]
 add('nhpp_predict',query[:,None],[shape,logeta],{'expected_cumulative_events':cumulative})
for _ in range(100):
 n=int(rng.integers(1,9));p=rng.uniform(.01,.99,n);k=int(rng.integers(1,n+1));total=0
 for mask in itertools.product([0,1],repeat=n):
  if sum(mask)>=k:total+=np.prod([p[j]if mask[j]else 1-p[j]for j in range(n)])
 add('reliability_blocks',[p],[2,k],{'reliabilities':[total]})
 add('reliability_blocks',[p],[0],{'reliabilities':[np.prod(p)]})
 add('reliability_blocks',[p],[1],{'reliabilities':[1-np.prod(1-p)]})
proc=subprocess.run(['/private/tmp/rusta-ducksmiles-jmp-target/reliability-check/runner'],input='\n'.join(c[0]for c in cases)+'\n',text=True,capture_output=True,check=True)
errors=[];maximum=(0,None)
for (_,op,expected),out in zip(cases,proc.stdout.splitlines()):
 if out.startswith('ERROR'):errors.append((op,out));continue
 actual=json.loads(out)
 for key,ee in expected.items():
  a=np.asarray(actual[key]);b=np.asarray(ee);error=float(np.max(abs(a-b)/np.maximum(1,abs(b))))
  if error>maximum[0]:maximum=error,(op,key)
  if error>2e-5:errors.append((op,key,error))
print(json.dumps({'cases':len(cases),'oracle_skipped':skipped,'max_scaled_absolute_error':maximum,'failure_count':len(errors),'errors':errors[:20]}))

